list_variations.code:
const response = await client.variations.listVariations({search: 'size', standard: 'text'});
for (const variation of response.map.variations) {
    console.log(variation.id, variation.name, variation.standard);
}

create_variation.code:
const response = await client.variations.createVariation({
    variation: {
        name: 'Shirt Size',
        standard: 'text',
        options: [
            {label: 'Small', value: 'S', order: 1, default: true},
            {label: 'Medium', value: 'M', order: 2},
        ],
    },
});
console.log(response.map.variation.id, response.map.variation.options);

get_variation.code:
const response = await client.variations.getVariation(12);
const variation = response.map.variation;
console.log(variation.name, variation.standard, variation.options);

update_variation.code:
const response = await client.variations.updateVariation(15, {
    variation: {
        name: 'Shirt Size',
        options: [
            {id: 201, label: 'Small', value: 'S', order: 1, default: true},
            {label: 'Large', value: 'L', order: 3},
        ],
    },
});
console.log(response.map.variation.options);

patch_variation.code:
const response = await client.variations.patchVariation(15, {
    variation: {
        options: [
            {id: 201, label: 'Petite'},
            {label: 'Extra Large', value: 'XL', order: 4},
        ],
    },
});
console.log(response.map.variation.options);

list_product_variations.code:
const response = await client.variations.listProductVariations(4321);
for (const group of response.map.variations) {
    for (const variant of group.variants) {
        console.log(variant.variation_id, variant.name, variant.pricing.base_price);
    }
}

update_product_variations.code:
const response = await client.variations.updateProductVariations(4321, {
    variation_ids: [91],
    available: true,
    available_stock: 12,
    min_order_quantity: 1,
    max_order_quantity: 5,
});
console.log(response.map.message);
for (const variant of response.map.updated) {
    console.log(variant.id, variant.name);
}
